import{_ as t}from"./index-B8M4sO0Z.js";import{o as e,c as i,f as s,a,e as n,w as l,t as o,q as r}from"./vendor-BqHjVcQx.js";const c={class:"min-h-screen pt-32 pb-20 px-6 max-w-4xl mx-auto text-white"},d={class:"mt-12 text-center space-x-6"},u=t({},[["render",function(t,u){const p=r("router-link");return e(),i("div",c,[u[3]||(u[3]=s('<h1 class="text-4xl font-bold mb-8">Cybersecurity Statement</h1><div class="space-y-8 text-neutral-300 leading-relaxed"><div class="p-4 bg-cyan-500/10 border border-cyan-500/30 rounded-xl"><p class="text-cyan-400 font-medium">Security is fundamental to our IT services. We apply the same rigorous standards to our own operations that we recommend to our clients.</p></div><section><h2 class="text-2xl font-bold text-white mb-4">1. Our Security Posture</h2><p>We don&#39;t wait for things to break. As an MSP providing IT services to businesses handling sensitive data, we apply the same rigorous security standards to ourselves that we enforce for our clients.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">2. Data Protection Measures</h2><ul class="list-disc list-inside space-y-3"><li><strong class="text-white">Encryption in Transit:</strong> All data transmitted to and from our systems uses TLS 1.3 encryption</li><li><strong class="text-white">Encryption at Rest:</strong> Client data is stored on encrypted storage systems</li><li><strong class="text-white">Access Controls:</strong> Principle of least privilege applied to all data access</li><li><strong class="text-white">Data Minimisation:</strong> We only collect and retain data necessary for service delivery</li><li><strong class="text-white">Secure Disposal:</strong> Storage media sanitised following NCSC guidance and industry best practices</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">3. Infrastructure Security</h2><ul class="list-disc list-inside space-y-3"><li><strong class="text-white">Endpoint Protection:</strong> Business devices protected by managed endpoint detection and response</li><li><strong class="text-white">Multi-Factor Authentication:</strong> MFA enforced on all critical systems and accounts</li><li><strong class="text-white">Network Security:</strong> Appropriate network security controls with traffic monitoring</li><li><strong class="text-white">Patch Management:</strong> Regular patching cycles with priority for critical vulnerabilities</li><li><strong class="text-white">Backup Strategy:</strong> Regular encrypted backups with documented recovery procedures</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">4. Website Security</h2><p>This website is protected by:</p><div class="mt-4 grid gap-3"><div class="p-3 bg-neutral-800 rounded-lg flex items-center gap-3"><span class="text-emerald-400 text-xl">🔒</span><div><p class="font-medium text-white">HTTPS Everywhere</p><p class="text-sm text-neutral-400">HSTS preload with 2-year max-age</p></div></div><div class="p-3 bg-neutral-800 rounded-lg flex items-center gap-3"><span class="text-emerald-400 text-xl">🛡️</span><div><p class="font-medium text-white">Content Security Policy</p><p class="text-sm text-neutral-400">Strict CSP headers to prevent XSS attacks</p></div></div><div class="p-3 bg-neutral-800 rounded-lg flex items-center gap-3"><span class="text-emerald-400 text-xl">🔐</span><div><p class="font-medium text-white">Security Headers</p><p class="text-sm text-neutral-400">X-Frame-Options, X-Content-Type-Options, Referrer-Policy</p></div></div></div></section><section><h2 class="text-2xl font-bold text-white mb-4">5. Staying Sharp</h2><p>We keep up with new threats by:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Regular security training and certifications</li><li>Monitoring of NCSC advisories and threat intelligence</li><li>Participation in cybersecurity communities and forums</li><li>Regular review and update of security practices</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">6. Incident Response</h2><p>In the event of a security incident affecting client data:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Immediate containment and investigation</li><li>Notification to affected parties within 72 hours (per UK GDPR)</li><li>ICO notification where legally required</li><li>Full post-incident review and remediation</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">7. Responsible Disclosure</h2><p>If you discover a security vulnerability on our website or systems, please report it responsibly to <a href="mailto:jake@jakefieldhouse.co.uk" class="text-blue-400 hover:underline">jake@jakefieldhouse.co.uk</a> with the subject line &quot;Security Vulnerability Report&quot;. We commit to:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Acknowledging your report within 48 hours</li><li>Keeping you informed of our investigation</li><li>Not pursuing legal action against good-faith security researchers</li></ul></section><p class="text-neutral-500 text-sm pt-8">Last updated: February 2026</p></div>',2)),a("div",d,[n(p,{to:"/security-acknowledgments",class:"text-neutral-500 hover:text-white transition-colors"},{default:l(()=>[...u[0]||(u[0]=[o("Security Acknowledgments",-1)])]),_:1}),n(p,{to:"/policies",class:"text-neutral-500 hover:text-white transition-colors"},{default:l(()=>[...u[1]||(u[1]=[o("← All Policies",-1)])]),_:1}),n(p,{to:"/",class:"text-neutral-500 hover:text-white transition-colors"},{default:l(()=>[...u[2]||(u[2]=[o("Back to Home",-1)])]),_:1})])])}]]);export{u as default};
